head.script:
scwin.gVar = {
    "cMandatory" : "",
    "cValue" : "",
    "cDisplaymessage" : "",
    "cInvalidMessage" : "",
    "cInvalidMessageFunc" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > mandatory]<br/>컴포넌트의 입력값 유효성 체크 시 입력값의 유/무를 확인하도록 설정합니다.",
    "validation" : [
        "validate() 메소드로 유효성 체크를 수행합니다.",
        "true 설정 시, 컴포넌트의 입력값 유/무를 확인합니다.",
        "true 설정 시, 'w2input_mandatory' 클래스가 추가됩니다.",
        "false 설정 시, 컴포넌트의 입력값 유/무를 확인하지 않습니다.",
        "미설정 시, 컴포넌트의 입력값 유/무를 확인하지 않습니다.",
        "컴포넌트에 입력값이 없는 경우 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 '필수 입력 항목입니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_mandatory.setValue("2");
    con_value.setValue("empty");
    con_displaymessage.setValue("2");
    con_invalidMessageFunc.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 mandatory 실패는 입력값이 없을 때만 발생하므로, Target 재생성 시 target1 의 값은 위 조건의 입력값 선택에 따라 빈값 또는 secret (6자) 으로 설정됩니다\n[절차] mandatory, 입력값, displaymessage (필요 시 invalidMessage, invalidMessageFunc) 선택 -> Target 재생성 -> validate 버튼 클릭\n[확인] 재생성 시 결과창에 출력되는 class 문자열, validate 버튼 클릭 시 결과창의 validate() 반환값과 alert 창의 표시 여부 및 문구"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMandatory"] = con_mandatory.getText();
    scwin.gVar["cValue"] = con_value.getValue();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getText();

    let properties = {
        mandatory : scwin.gVar["cMandatory"],
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessage : scwin.gVar["cInvalidMessage"],
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값 secret 을 입력값 조건에 맞춰 덮음 (빈값 선택 시 mandatory 실패 상황 재현)
    if (scwin.gVar["cValue"] === "empty")
        target1.setValue("");

    scwin.printCompClass();
}



// validation 3 판정 출력 (mandatory 값별 class 문자열)
scwin.printCompClass = function () {
    let strMandatory = (scwin.gVar["cMandatory"] === "") ? "미설정" : scwin.gVar["cMandatory"];

    wf_body_bottom.getObj("scwin").setReturnValue("mandatory " + strMandatory + " -> class : " + target1.render.className);
}



// validate 실행 (mandatory 발동 수단) - validation 1, 2, 4, 5, 6, 7 판정 출력
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이를 함께 출력
    let nLength = (target1.getValue() || "").length;
    let rtn = target1.validate();

    let strMandatory = (scwin.gVar["cMandatory"] === "") ? "미설정" : scwin.gVar["cMandatory"];
    let strDisplaymessage = (scwin.gVar["cDisplaymessage"] === "") ? "미설정" : scwin.gVar["cDisplaymessage"];
    let strInvalidMessage = (scwin.gVar["cInvalidMessage"] === "") ? "미설정" : scwin.gVar["cInvalidMessage"];
    let strInvalidMessageFunc = (scwin.gVar["cInvalidMessageFunc"] === "") ? "미설정" : scwin.gVar["cInvalidMessageFunc"];

    wf_body_bottom.getObj("scwin").setReturnValue("mandatory " + strMandatory + " / target1 값 길이 " + nLength + " / displaymessage " + strDisplaymessage + " / invalidMessage " + strInvalidMessage + " / invalidMessageFunc " + strInvalidMessageFunc + " -> validate() 반환값 : " + rtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수
scwin.fn_msg = function () {
    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ")";
}
